ery"]},{"allowed_semantic_states":["OBSERVED","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Generate required narrative forms from available trusted evidence"],"completeness_rules":["COMPLETE when required narratives were generated and every factual claim is grounded"],"description":"Create evidence-grounded human-readable summaries of the asset and important scenes/events.","evidence_requirements":["Every factual narrative claim links to trusted structured evidence"],"expected_information":["short description","detailed/master description","scene narrative","narrative claims","evidence linkage","confidence/uncertainty","search eligibility status"],"fallback_behavior":"Produce a narrower narrative from reliable evidence rather than filling gaps.","layer_id":"SEMANTIC_NARRATIVE","layer_name":"Semantic Narrative","layer_number":17,"modality_dependencies":["structured semantic assertions","scene/event structure","trusted metadata/context"],"prohibited_inferences":["Narrative may not create facts unsupported by structured semantic evidence"],"purpose":"Provide readable synthesis without creating new facts.","quality_rules":["Narrative must expose material uncertainty"],"search_critical_fields":["short description","master description","grounded scene narrative"],"search_inclusion_rules":["Include only narratives eligible under the locked grounded-narrative policy"]},{"allowed_semantic_states":["OBSERVED","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Build from all reliable available evidence","No single modality is mandatory"],"completeness_rules":["COMPLETE when all required representations applicable to the asset were built","An unavailable modality alone does not make the layer PARTIAL"],"description":"Create reusable search representations from trusted semantic evidence.","evidence_requirements":["Every included representation traces to trusted evidence and the current locked semantic version"],"expected_information":["canonical search document","normalized search text","positive concepts","supported negative concepts","search-document fingerprint","text embedding","visual embedding where applicable","scene embedding where applicable","embedding provider/model/version","dimension","evidence lineage"],"fallback_behavior":"Build the applicable subset of search representations from trusted available evidence.","layer_id":"SEARCH_EMBEDDINGS","layer_name":"Search & Embeddings","layer_number":18,"modality_dependencies":["all reliable available modalities"],"prohibited_inferences":["Do not require audio, OCR, treatment, identity, or any single modality","Do not include unsupported negative concepts"],"purpose":"Provide the primary retrieval representation with complete evidence lineage.","quality_rules":["Exclude rejected, hallucinated, or ungrounded material"],"search_critical_fields":["canonical search document","normalized search text","concepts","embeddings","provider/model/version","evidence lineage"],"search_inclusion_rules":["PRIMARY RETRIEVAL REPRESENTATION","Combine relevant available evidence; do not privilege a fixed primary field"]}],"spec_fingerprint":"6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7","spec_version":"kdi_semantic_18_layer_v1","status":"LOCKED"}'::jsonb,'{"display_version":"KDI_SEMANTIC_18_LAYER_V1","fingerprint_contract":{"algorithm":"SHA-256","canonicalization":"UTF-8 JSON; lexicographically sorted object keys; compact separators comma and colon; omit only top-level spec_fingerprint"},"global_rules":{"blurry_low_quality":"Record supported quality evidence such as blur, motion blur, low resolution, poor exposure, occlusion, or unstable camera. Store only semantic facts that remain supportable. Never guess treatment, anatomy, role, identity, action, or clinical condition from a blurry medical-looking scene.","canonical_search_document":"Combine trusted available structured 18-layer evidence, master/global description, scene/event facts, accepted transcript, accepted OCR, safe metadata, search concepts, and embeddings. Audio, OCR, treatment classification, person identity, and every other single modality are optional.","completeness":"Completeness answers whether the layer fully evaluated all applicable requirements in this locked specification; it does not measure the number of positive facts. COMPLETE may contain UNKNOWN, NOT_APPLICABLE, or zero positive assertions. Processing status and completeness status are independent and completeness must be actively computed rather than left at an insertion default.","completeness_status":["COMPLETE","PARTIAL","NOT_EVALUATED"],"evidence_trust_guidance":["deterministic asset identity / technical metadata","direct structured semantic observations","scene/event evidence","trusted normalized semantic evidence","semantic narrative grounded in evidence","accepted transcript evidence","accepted OCR evidence","semantic text similarity","visual similarity"],"evidence_trust_guidance_is_override_rule":false,"future_run_contract":"Before analysis begins, a worker must resolve and record semantic_spec_version and semantic_spec_fingerprint, and fail closed when its expected values do not match the locked canonical specification.","modality_fallback":{"missing_modalities_block_indexing":false,"modalities":["technical/file metadata","visual observations","scene/event structure","speech/audio","OCR/visible text","structured semantic assertions","semantic narrative","trusted metadata/context","derived search representations","embeddings"],"rule":"INDEX FROM ALL RELIABLE AVAILABLE MODALITIES.","single_primary_field_required":false},"no_audio":"If an asset has no audio track, SPEECH_TRANSCRIPT_AUDIO is NOT_APPLICABLE. Do not invent transcript, language, or speaker; do not mark extraction failed or block indexing. If audio exists but speech is not understandable, transcript/language facts are UNKNOWN or an observed no-intelligible-speech fact when supported.","no_visible_text":"If no visible text exists, OCR_VISIBLE_TEXT is NOT_APPLICABLE. If text appears present but cannot be read reliably, OCR_VISIBLE_TEXT is UNKNOWN. Never hallucinate text and never let OCR failure block visual indexing.","processing_status":["PENDING","RUNNING","COMPLETE","FAILED"],"semantic_states":{"FALSE":"Reliable evidence explicitly supports the proposition being false; it never means the model did not see it.","NOT_APPLICABLE":"The question or modality does not apply to the asset or layer and is not an extraction failure.","OBSERVED":"Reliable evidence supports the proposition.","UNKNOWN":"Insufficient reliable evidence exists to determine the proposition.","allowed":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"invariants":["UNKNOWN != FALSE","ABSENCE OF EVIDENCE IS NOT EVIDENCE OF ABSENCE"]}},"layers":[{"allowed_semantic_states":["OBSERVED","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to every asset","Uses deterministic metadata"],"completeness_rules":["COMPLETE when all applicable required deterministic fields available to the pipeline were evaluated and provenance linkage is valid","Unavailable optional metadata alone does not make the layer PARTIAL"],"description":"Identify the canonical asset and deterministic source/provenance information needed to trace the file.","evidence_requirements":["Deterministic file, source-system, or ingestion records","Valid provenance linkage"],"expected_information":["canonical asset ID","filename","extension","media type","MIME type","file size","dimensions","duration","source system","source folder","source file reference","destination reference","checksums/hashes","ingestion timestamp","modification timestamp","analysis version","provenance lineage"],"fallback_behavior":"Preserve known deterministic facts and mark genuinely indeterminate applicable facts UNKNOWN.","layer_id":"ASSET_IDENTITY_PROVENANCE","layer_name":"Asset Identity & Provenance","layer_number":1,"modality_dependencies":["technical/file metadata"],"prohibited_inferences":["Do not infer semantic content from filename unless separately labeled metadata-derived inference"],"purpose":"Trace identity and lineage without semantic guessing.","quality_rules":["Metadata availability is evaluated independently of visual or audio quality"],"search_critical_fields":["canonical asset ID","filename","media type","checksums/hashes"],"search_inclusion_rules":["Include filename, media type, safe technical metadata, and appropriate provenance fields"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to every usable asset","Videos use representative scene/event evidence","Images use full-frame evidence"],"completeness_rules":["COMPLETE when all applicable global categories were evaluated, including explicit UNKNOWN where evidence is insufficient"],"description":"Provide a concise evidence-grounded understanding of the whole asset.","evidence_requirements":["Claims must link to reliable whole-frame or representative scene/event evidence"],"expected_information":["primary visible subject/content","main activity","broad setting","overall media purpose where supportable","general clinical/non-clinical context","short description","master description","uncertainty"],"fallback_behavior":"Build the best grounded global account from all reliable available modalities.","layer_id":"GLOBAL_ASSET_UNDERSTANDING","layer_name":"Global Asset Understanding","layer_number":2,"modality_dependencies":["visual observations","scene/event structure","trusted metadata/context"],"prohibited_inferences":["Do not invent treatment, identity, diagnosis, or intent"],"purpose":"Summarize primary content, activity, setting, purpose, and uncertainty.","quality_rules":["Low-quality evidence narrows claims rather than forcing PARTIAL"],"search_critical_fields":["primary content","main activity","setting","short description","master description"],"search_inclusion_rules":["HIGH contribution from grounded global descriptions and categories"]},{"allowed_semantic_states":["OBSERVED","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to video","Still images are NOT_APPLICABLE"],"completeness_rules":["Video is COMPLETE when temporal analysis successfully covers full usable duration","Still image is NOT_APPLICABLE rather than PARTIAL"],"description":"Represent time-based organization of video assets.","evidence_requirements":["Full usable video duration evaluated under the locked segmentation policy"],"expected_information":["scene boundaries","start/end time","scene order","keyframes","event windows","supported temporal transitions"],"fallback_behavior":"Do not block non-temporal indexing when temporal structure is not applicable or partly unavailable.","layer_id":"TEMPORAL_SCENE_STRUCTURE","layer_name":"Temporal / Scene Structure","layer_number":3,"modality_dependencies":["scene/event structure","visual observations"],"prohibited_inferences":["Do not invent unseen events or transitions"],"purpose":"Support temporal evidence and scene-level retrieval.","quality_rules":["Unusable intervals may be UNKNOWN with explicit quality evidence"],"search_critical_fields":["scene boundaries","timestamps","event windows"],"search_inclusion_rules":["Include scene-level retrieval and temporal evidence"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate every visible person meeting detection thresholds"],"completeness_rules":["COMPLETE when all qualifying visible persons were evaluated for role","UNKNOWN role is a completed evaluation"],"description":"Represent visible people and their evidence-supported roles.","evidence_requirements":["Visible person evidence and role-specific cues or trusted context"],"expected_information":["person instance","visible-person count","clinician","doctor where supportable","patient","assistant/staff","subject","unknown role","role confidence","scene association"],"fallback_behavior":"Retain person presence/count while leaving unsupported roles UNKNOWN.","layer_id":"PEOPLE_ROLES","layer_name":"People & Roles","layer_number":4,"modality_dependencies":["visual observations","scene/event structure","trusted metadata/context"],"prohibited_inferences":["Do not identify a specific person without approved identity evidence","Do not guess clinical roles from clothing or setting alone"],"purpose":"Make people and supported roles searchable without unauthorized identity inference.","quality_rules":["If a person is visible but role cues are insufficient, role is UNKNOWN"],"search_critical_fields":["person count","role","scene association"],"search_inclusion_rules":["HIGH contribution for supported people and role facts"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies when a person is visibly assessable","Sensitive demographic inference follows project policy"],"completeness_rules":["COMPLETE when applicable allowed appearance categories were evaluated","UNKNOWN is valid completion"],"description":"Describe visible search-useful presentation characteristics without inventing sensitive identity attributes.","evidence_requirements":["Direct visible evidence for each asserted characteristic"],"expected_information":["apparent adult/child presentation where appropriate","hair visibility","hair length","hair color","hair density/pattern","clothing","PPE","gloves","mask","eyewear","posture","reclining/seated/standing","face visibility","scalp visibility","body orientation","presentation state"],"fallback_behavior":"Use UNKNOWN for unresolved visible characteristics and NOT_APPLICABLE when no person is present.","layer_id":"PERSON_APPEARANCE","layer_name":"Person Appearance","layer_number":5,"modality_dependencies":["visual observations"],"prohibited_inferences":["Do not infer ethnicity from appearance","Do not manufacture exact age","Do not infer identity"],"purpose":"Support appearance queries within privacy and sensitive-inference policy.","quality_rules":["Occluded or blurry characteristics are UNKNOWN"],"search_critical_fields":["clothing/PPE","posture","face/scalp visibility","body orientation"],"search_inclusion_rules":["Include only policy-allowed field-specific appearance facts"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies when anatomy is visible or otherwise directly evidenced"],"completeness_rules":["COMPLETE when applicable visible anatomy was evaluated across usable evidence","UNKNOWN is valid when anatomy cannot be resolved"],"description":"Identify visible anatomical regions relevant to search.","evidence_requirements":["Direct reliable anatomy evidence with scene association"],"expected_information":["canonical anatomy concept","scalp","frontal scalp","frontal hairline","cheek","face","lower face","lips","neck","donor region","recipient region","scene association","evidence","confidence","primary/secondary anatomy"],"fallback_behavior":"Preserve broad supported regions and mark finer localization UNKNOWN.","layer_id":"ANATOMY","layer_name":"Anatomy","layer_number":6,"modality_dependencies":["visual observations","scene/event structure"],"prohibited_inferences":["Do not infer anatomy solely from treatment name"],"purpose":"Normalize supported anatomy for precise retrieval.","quality_rules":["Blur, occlusion, or framing may require UNKNOWN"],"search_critical_fields":["canonical anatomy concept","scene association"],"search_inclusion_rules":["VERY HIGH contribution from supported canonical anatomy"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate whether treatment classification applies","No treatment evidence may yield UNKNOWN or NOT_APPLICABLE according to evaluated context"],"completeness_rules":["COMPLETE when treatment applicability was evaluated","UNKNOWN treatment can coexist with COMPLETE evaluation"],"description":"Identify treatment or procedure only when evidence supports the classification.","evidence_requirements":["Treatment-specific visual, textual, transcript, or trusted contextual evidence"],"expected_information":["canonical treatment concept","procedure stage","primary treatment","related treatment evidence","confidence","scene association"],"fallback_behavior":"Keep supported anatomy/action facts while treatment remains UNKNOWN.","layer_id":"TREATMENT_PROCEDURE","layer_name":"Treatment / Procedure","layer_number":7,"modality_dependencies":["visual observations","scene/event structure","speech/audio","OCR/visible text","trusted metadata/context"],"prohibited_inferences":["Anatomy plus action does not prove a specific treatment","Neck plus injection does not prove Botox, filler, mesotherapy, or PRP"],"purpose":"Provide high-value treatment retrieval without unsafe clinical guessing.","quality_rules":["Ambiguous or low-quality procedure evidence is UNKNOWN"],"search_critical_fields":["canonical treatment concept","procedure stage","scene association"],"search_inclusion_rules":["VERY HIGH contribution only when OBSERVED and trusted"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate relevant visible or otherwise reliable actions/events"],"completeness_rules":["COMPLETE when relevant actions/events were evaluated","UNKNOWN is permitted"],"description":"Identify visible or otherwise evidenced actions and events.","evidence_requirements":["Direct visual, temporal, audio, or trusted evidence"],"expected_information":["injecting","drawing","marking","cleansing","touching","examining","using device","implanting grafts","speaking","posing","recording video","actor","target","scene/event","confidence","temporal interval"],"fallback_behavior":"Store only the broadest action supportable; otherwise UNKNOWN.","layer_id":"ACTIONS_EVENTS","layer_name":"Actions & Events","layer_number":8,"modality_dependencies":["visual observations","scene/event structure","speech/audio"],"prohibited_inferences":["Do not infer a specific action from setting alone","Do not infer treatment from an action"],"purpose":"Represent what happens, who acts, and what is targeted.","quality_rules":["Do not over-specify ambiguous motion"],"search_critical_fields":["canonical action","actor","target","temporal interval"],"search_inclusion_rules":["VERY HIGH contribution for trusted actions and events"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate detected entities/actions for supported search-relevant relations"],"completeness_rules":["COMPLETE when applicable detected entities/actions were evaluated for supported relations"],"description":"Represent evidence-supported relationships between entities.","evidence_requirements":["All relation endpoints and the relation itself must be evidenced"],"expected_information":["subject entity","relationship type","object entity","clinician treats patient","clinician touches cheek","syringe applied to neck","clinician works on scalp","person uses device","action targets anatomy","scene/event context","evidence","confidence"],"fallback_behavior":"Index supported independent entities/actions even when their relationship is UNKNOWN.","layer_id":"RELATIONSHIPS","layer_name":"Relationships","layer_number":9,"modality_dependencies":["structured semantic assertions","scene/event structure","visual observations"],"prohibited_inferences":["Do not invent absence or presence of a relationship"],"purpose":"Support relational natural-language queries.","quality_rules":["Uncertain endpoints or linkage produce UNKNOWN rather than a guessed relation"],"search_critical_fields":["subject","relationship","object","scene/event"],"search_inclusion_rules":["HIGH contribution for trusted relational facts"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to defined observable clinical categories when evidence exists"],"completeness_rules":["COMPLETE when applicable defined clinical-observation categories were evaluated"],"description":"Store observable clinical facts without unsupported diagnosis.","evidence_requirements":["Direct observable evidence linked to anatomy and scene where relevant"],"expected_information":["visible frontal thinning","visible injection at neck","treatment area prepared","hairline markings visible","scalp under active clinical attention","eye protection visible","clinical instrument visible","observation code","anatomical context","scene","evidence","confidence"],"fallback_behavior":"Use non-diagnostic broad observation or UNKNOWN.","layer_id":"CLINICAL_VISUAL_OBSERVATIONS","layer_name":"Clinical Visual Observations","layer_number":10,"modality_dependencies":["visual observations","scene/event structure"],"prohibited_inferences":["No diagnosis unless explicitly supported by approved clinical evidence and policy"],"purpose":"Capture clinically useful visual facts while separating observation from diagnosis.","quality_rules":["Low quality limits observations to what remains directly supportable"],"search_critical_fields":["observation code","anatomical context","scene"],"search_inclusion_rules":["HIGH contribution for grounded observation codes"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate visible environment for every usable visual asset"],"completeness_rules":["COMPLETE when applicable environmental categories were evaluated"],"description":"Describe the physical setting.","evidence_requirements":["Direct visual setting evidence or trusted location context"],"expected_information":["treatment room","consultation room","studio","indoor room","neutral background","clinical environment","outdoor environment","background","visible equipment context","location class","confidence"],"fallback_behavior":"Use broad indoor/outdoor/unknown setting when finer classification is unsupported.","layer_id":"ENVIRONMENT","layer_name":"Environment","layer_number":11,"modality_dependencies":["visual observations","trusted metadata/context"],"prohibited_inferences":["Do not infer a clinic or exact location from weak aesthetic cues"],"purpose":"Support setting and background discovery.","quality_rules":["Tight framing may make detailed environment UNKNOWN"],"search_critical_fields":["environment category","background","equipment context"],"search_inclusion_rules":["MEDIUM contribution for supported setting facts"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to usable visual media"],"completeness_rules":["COMPLETE when applicable capture/quality categories were evaluated","Observed blur does not make completeness PARTIAL"],"description":"Describe how the media was captured, including technical visual quality.","evidence_requirements":["Direct frame or sequence evidence"],"expected_information":["close-up","extreme close-up","medium","wide","front angle","side angle","handheld","static","moving camera","orientation","camera movement","technical quality","blur","focus","exposure"],"fallback_behavior":"Record supported capture facts even when semantic subjects remain unknown.","layer_id":"CINEMATOGRAPHY","layer_name":"Cinematography","layer_number":12,"modality_dependencies":["visual observations","scene/event structure","technical/file metadata"],"prohibited_inferences":["Do not translate technical quality into unsupported semantic content"],"purpose":"Support capture-style and quality-based discovery.","quality_rules":["Low-quality imagery can still yield a COMPLETE cinematography evaluation"],"search_critical_fields":["shot size","angle","motion","orientation","quality"],"search_inclusion_rules":["MEDIUM/HIGH contribution when capture qualities are requested"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Applies to usable visual media"],"completeness_rules":["COMPLETE when applicable composition categories were evaluated"],"description":"Describe spatial framing and visual arrangement.","evidence_requirements":["Direct spatial/frame evidence"],"expected_information":["primary subject","central/off-center framing","foreground/background","subject prominence","treatment area prominence","single/multiple subject composition","face/scalp/body prominence","visual clutter"],"fallback_behavior":"Describe geometry and prominence without guessing subject semantics.","layer_id":"COMPOSITION","layer_name":"Composition","layer_number":13,"modality_dependencies":["visual observations"],"prohibited_inferences":["Do not infer treatment or identity from prominence"],"purpose":"Support framing, prominence, and layout queries.","quality_rules":["Blur may affect semantic identification without preventing layout evaluation"],"search_critical_fields":["primary subject","framing","prominence","subject count"],"search_inclusion_rules":["MEDIUM contribution for supported composition facts"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["No audio track is NOT_APPLICABLE","Audio without speech uses the ontology no-speech state","Unintelligible speech makes transcript/language facts UNKNOWN"],"completeness_rules":["COMPLETE when applicability was evaluated and all usable speech processed under audio policy","Silent/no-audio files may be COMPLETE/NOT_APPLICABLE rather than PARTIAL"],"description":"Represent usable audio and speech evidence.","evidence_requirements":["Audio-track probe and accepted audio/speech processing output"],"expected_information":["has_audio","has_speech","language","transcript chunks","speaker labels","spoken summary","audio event","confidence","timestamps"],"fallback_behavior":"Continue all non-audio layers and indexing when audio is missing or unusable.","layer_id":"SPEECH_TRANSCRIPT_AUDIO","layer_name":"Speech / Transcript / Audio","layer_number":14,"modality_dependencies":["speech/audio","technical/file metadata"],"prohibited_inferences":["Never invent transcript, language, speaker, or audio events"],"purpose":"Capture trusted audio, speech, language, and transcript evidence without fabrication.","quality_rules":["Unintelligible speech is UNKNOWN and never fabricated"],"search_critical_fields":["accepted transcript","language","audio event","timestamps"],"search_inclusion_rules":["Include only trusted/accepted transcript and audio evidence"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["No visible text is NOT_APPLICABLE","Visible but unreadable text is UNKNOWN","Readable text is OBSERVED with transcription and confidence"],"completeness_rules":["COMPLETE when applicable frames/scenes were evaluated under OCR policy","Zero text is not extraction failure"],"description":"Represent visible readable text.","evidence_requirements":["Frame/region evidence and OCR confidence/acceptance decision"],"expected_information":["detected text","location/region","scene/time","confidence","accepted/rejected search status"],"fallback_behavior":"Continue visual indexing when OCR is absent, unreadable, or rejected.","layer_id":"OCR_VISIBLE_TEXT","layer_name":"OCR / Visible Text","layer_number":15,"modality_dependencies":["OCR/visible text","visual observations","scene/event structure"],"prohibited_inferences":["Never hallucinate text","Unreadable OCR does not prove no text exists"],"purpose":"Capture trusted visible text with spatial and temporal provenance.","quality_rules":["Unreadable visible text is UNKNOWN"],"search_critical_fields":["accepted text","location/region","scene/time"],"search_inclusion_rules":["Include only accepted/trusted OCR"]},{"allowed_semantic_states":["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Evaluate defined marketing-content categories when supportable"],"completeness_rules":["COMPLETE when defined marketing-content categories were evaluated"],"description":"Describe content characteristics useful for discovery and distribution planning without representing consent.","evidence_requirements":["Grounded content, orientation, and quality evidence"],"expected_information":["testimonial potential","procedure footage","portrait content","before/after suitability","educational content","promotional candidate","social-media suitability","orientation suitability","quality limitations"],"fallback_behavior":"Return UNKNOWN suitability where content evidence is insufficient; governance remains external.","layer_id":"MARKETING_CONTENT_USAGE","layer_name":"Marketing & Content Usage","layer_number":16,"modality_dependencies":["visual observations","scene/event structure","semantic narrative","technical/file metadata"],"prohibited_inferences":["Marketing suitability is not patient consent","Do not infer ACL, rights, or consent"],"purpose":"Support content-planning queries while keeping governance separate.","quality_rules":["Record limitations explicitly"],"search_critical_fields":["content type","potential use","orientation suitability","quality limitations"],"search_inclusion_rules":["Include only when relevant to the query"]},{"allowed_semantic_states":["OBSERVED","UNKNOWN","NOT_APPLICABLE"],"applicability_rules":["Generate required narrative forms from available trusted evidence"],"completeness_rules":["COMPLETE when required narratives were generated and every factual claim is grounded"],"description":"Create evidence-grounded human-readable summaries of the asset and important scenes/events.","evidence_requirements":["Every factual narrative claim links to trusted structured evidence"],"expected_information":["short description","detailed/master description","scene narrative","narrative claims","evidence linkage","confidence/uncertainty","search eligibility status"],"fallback_behavior":"Produce a narrower narrative from reliable evidence rather than filling gaps.","layer_id":"SEMANTIC_NARRATIVE","layer_name"