values
('kdi_semantic_18_layer_v1','ASSET_IDENTITY_PROVENANCE',1,'Asset Identity & Provenance','Identify the canonical asset and deterministic source/provenance information needed to trace the file.','Trace identity and lineage without semantic guessing.','["Applies to every asset","Uses deterministic metadata"]'::jsonb,'["canonical asset ID","filename","extension","media type","MIME type","file size","dimensions","duration","source system","source folder","source file reference","destination reference","checksums/hashes","ingestion timestamp","modification timestamp","analysis version","provenance lineage"]'::jsonb,'["OBSERVED","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Deterministic file, source-system, or ingestion records","Valid provenance linkage"]'::jsonb,'["COMPLETE when all applicable required deterministic fields available to the pipeline were evaluated and provenance linkage is valid","Unavailable optional metadata alone does not make the layer PARTIAL"]'::jsonb,'["Include filename, media type, safe technical metadata, and appropriate provenance fields"]'::jsonb,'["canonical asset ID","filename","media type","checksums/hashes"]'::jsonb,'["technical/file metadata"]'::jsonb,'["Metadata availability is evaluated independently of visual or audio quality"]'::jsonb,'["Do not infer semantic content from filename unless separately labeled metadata-derived inference"]'::jsonb,'Preserve known deterministic facts and mark genuinely indeterminate applicable facts UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','GLOBAL_ASSET_UNDERSTANDING',2,'Global Asset Understanding','Provide a concise evidence-grounded understanding of the whole asset.','Summarize primary content, activity, setting, purpose, and uncertainty.','["Applies to every usable asset","Videos use representative scene/event evidence","Images use full-frame evidence"]'::jsonb,'["primary visible subject/content","main activity","broad setting","overall media purpose where supportable","general clinical/non-clinical context","short description","master description","uncertainty"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Claims must link to reliable whole-frame or representative scene/event evidence"]'::jsonb,'["COMPLETE when all applicable global categories were evaluated, including explicit UNKNOWN where evidence is insufficient"]'::jsonb,'["HIGH contribution from grounded global descriptions and categories"]'::jsonb,'["primary content","main activity","setting","short description","master description"]'::jsonb,'["visual observations","scene/event structure","trusted metadata/context"]'::jsonb,'["Low-quality evidence narrows claims rather than forcing PARTIAL"]'::jsonb,'["Do not invent treatment, identity, diagnosis, or intent"]'::jsonb,'Build the best grounded global account from all reliable available modalities.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','TEMPORAL_SCENE_STRUCTURE',3,'Temporal / Scene Structure','Represent time-based organization of video assets.','Support temporal evidence and scene-level retrieval.','["Applies to video","Still images are NOT_APPLICABLE"]'::jsonb,'["scene boundaries","start/end time","scene order","keyframes","event windows","supported temporal transitions"]'::jsonb,'["OBSERVED","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Full usable video duration evaluated under the locked segmentation policy"]'::jsonb,'["Video is COMPLETE when temporal analysis successfully covers full usable duration","Still image is NOT_APPLICABLE rather than PARTIAL"]'::jsonb,'["Include scene-level retrieval and temporal evidence"]'::jsonb,'["scene boundaries","timestamps","event windows"]'::jsonb,'["scene/event structure","visual observations"]'::jsonb,'["Unusable intervals may be UNKNOWN with explicit quality evidence"]'::jsonb,'["Do not invent unseen events or transitions"]'::jsonb,'Do not block non-temporal indexing when temporal structure is not applicable or partly unavailable.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','PEOPLE_ROLES',4,'People & Roles','Represent visible people and their evidence-supported roles.','Make people and supported roles searchable without unauthorized identity inference.','["Evaluate every visible person meeting detection thresholds"]'::jsonb,'["person instance","visible-person count","clinician","doctor where supportable","patient","assistant/staff","subject","unknown role","role confidence","scene association"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Visible person evidence and role-specific cues or trusted context"]'::jsonb,'["COMPLETE when all qualifying visible persons were evaluated for role","UNKNOWN role is a completed evaluation"]'::jsonb,'["HIGH contribution for supported people and role facts"]'::jsonb,'["person count","role","scene association"]'::jsonb,'["visual observations","scene/event structure","trusted metadata/context"]'::jsonb,'["If a person is visible but role cues are insufficient, role is UNKNOWN"]'::jsonb,'["Do not identify a specific person without approved identity evidence","Do not guess clinical roles from clothing or setting alone"]'::jsonb,'Retain person presence/count while leaving unsupported roles UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','PERSON_APPEARANCE',5,'Person Appearance','Describe visible search-useful presentation characteristics without inventing sensitive identity attributes.','Support appearance queries within privacy and sensitive-inference policy.','["Applies when a person is visibly assessable","Sensitive demographic inference follows project policy"]'::jsonb,'["apparent adult/child presentation where appropriate","hair visibility","hair length","hair color","hair density/pattern","clothing","PPE","gloves","mask","eyewear","posture","reclining/seated/standing","face visibility","scalp visibility","body orientation","presentation state"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct visible evidence for each asserted characteristic"]'::jsonb,'["COMPLETE when applicable allowed appearance categories were evaluated","UNKNOWN is valid completion"]'::jsonb,'["Include only policy-allowed field-specific appearance facts"]'::jsonb,'["clothing/PPE","posture","face/scalp visibility","body orientation"]'::jsonb,'["visual observations"]'::jsonb,'["Occluded or blurry characteristics are UNKNOWN"]'::jsonb,'["Do not infer ethnicity from appearance","Do not manufacture exact age","Do not infer identity"]'::jsonb,'Use UNKNOWN for unresolved visible characteristics and NOT_APPLICABLE when no person is present.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','ANATOMY',6,'Anatomy','Identify visible anatomical regions relevant to search.','Normalize supported anatomy for precise retrieval.','["Applies when anatomy is visible or otherwise directly evidenced"]'::jsonb,'["canonical anatomy concept","scalp","frontal scalp","frontal hairline","cheek","face","lower face","lips","neck","donor region","recipient region","scene association","evidence","confidence","primary/secondary anatomy"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct reliable anatomy evidence with scene association"]'::jsonb,'["COMPLETE when applicable visible anatomy was evaluated across usable evidence","UNKNOWN is valid when anatomy cannot be resolved"]'::jsonb,'["VERY HIGH contribution from supported canonical anatomy"]'::jsonb,'["canonical anatomy concept","scene association"]'::jsonb,'["visual observations","scene/event structure"]'::jsonb,'["Blur, occlusion, or framing may require UNKNOWN"]'::jsonb,'["Do not infer anatomy solely from treatment name"]'::jsonb,'Preserve broad supported regions and mark finer localization UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','TREATMENT_PROCEDURE',7,'Treatment / Procedure','Identify treatment or procedure only when evidence supports the classification.','Provide high-value treatment retrieval without unsafe clinical guessing.','["Evaluate whether treatment classification applies","No treatment evidence may yield UNKNOWN or NOT_APPLICABLE according to evaluated context"]'::jsonb,'["canonical treatment concept","procedure stage","primary treatment","related treatment evidence","confidence","scene association"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Treatment-specific visual, textual, transcript, or trusted contextual evidence"]'::jsonb,'["COMPLETE when treatment applicability was evaluated","UNKNOWN treatment can coexist with COMPLETE evaluation"]'::jsonb,'["VERY HIGH contribution only when OBSERVED and trusted"]'::jsonb,'["canonical treatment concept","procedure stage","scene association"]'::jsonb,'["visual observations","scene/event structure","speech/audio","OCR/visible text","trusted metadata/context"]'::jsonb,'["Ambiguous or low-quality procedure evidence is UNKNOWN"]'::jsonb,'["Anatomy plus action does not prove a specific treatment","Neck plus injection does not prove Botox, filler, mesotherapy, or PRP"]'::jsonb,'Keep supported anatomy/action facts while treatment remains UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','ACTIONS_EVENTS',8,'Actions & Events','Identify visible or otherwise evidenced actions and events.','Represent what happens, who acts, and what is targeted.','["Evaluate relevant visible or otherwise reliable actions/events"]'::jsonb,'["injecting","drawing","marking","cleansing","touching","examining","using device","implanting grafts","speaking","posing","recording video","actor","target","scene/event","confidence","temporal interval"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct visual, temporal, audio, or trusted evidence"]'::jsonb,'["COMPLETE when relevant actions/events were evaluated","UNKNOWN is permitted"]'::jsonb,'["VERY HIGH contribution for trusted actions and events"]'::jsonb,'["canonical action","actor","target","temporal interval"]'::jsonb,'["visual observations","scene/event structure","speech/audio"]'::jsonb,'["Do not over-specify ambiguous motion"]'::jsonb,'["Do not infer a specific action from setting alone","Do not infer treatment from an action"]'::jsonb,'Store only the broadest action supportable; otherwise UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','RELATIONSHIPS',9,'Relationships','Represent evidence-supported relationships between entities.','Support relational natural-language queries.','["Evaluate detected entities/actions for supported search-relevant relations"]'::jsonb,'["subject entity","relationship type","object entity","clinician treats patient","clinician touches cheek","syringe applied to neck","clinician works on scalp","person uses device","action targets anatomy","scene/event context","evidence","confidence"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["All relation endpoints and the relation itself must be evidenced"]'::jsonb,'["COMPLETE when applicable detected entities/actions were evaluated for supported relations"]'::jsonb,'["HIGH contribution for trusted relational facts"]'::jsonb,'["subject","relationship","object","scene/event"]'::jsonb,'["structured semantic assertions","scene/event structure","visual observations"]'::jsonb,'["Uncertain endpoints or linkage produce UNKNOWN rather than a guessed relation"]'::jsonb,'["Do not invent absence or presence of a relationship"]'::jsonb,'Index supported independent entities/actions even when their relationship is UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','CLINICAL_VISUAL_OBSERVATIONS',10,'Clinical Visual Observations','Store observable clinical facts without unsupported diagnosis.','Capture clinically useful visual facts while separating observation from diagnosis.','["Applies to defined observable clinical categories when evidence exists"]'::jsonb,'["visible frontal thinning","visible injection at neck","treatment area prepared","hairline markings visible","scalp under active clinical attention","eye protection visible","clinical instrument visible","observation code","anatomical context","scene","evidence","confidence"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct observable evidence linked to anatomy and scene where relevant"]'::jsonb,'["COMPLETE when applicable defined clinical-observation categories were evaluated"]'::jsonb,'["HIGH contribution for grounded observation codes"]'::jsonb,'["observation code","anatomical context","scene"]'::jsonb,'["visual observations","scene/event structure"]'::jsonb,'["Low quality limits observations to what remains directly supportable"]'::jsonb,'["No diagnosis unless explicitly supported by approved clinical evidence and policy"]'::jsonb,'Use non-diagnostic broad observation or UNKNOWN.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','ENVIRONMENT',11,'Environment','Describe the physical setting.','Support setting and background discovery.','["Evaluate visible environment for every usable visual asset"]'::jsonb,'["treatment room","consultation room","studio","indoor room","neutral background","clinical environment","outdoor environment","background","visible equipment context","location class","confidence"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct visual setting evidence or trusted location context"]'::jsonb,'["COMPLETE when applicable environmental categories were evaluated"]'::jsonb,'["MEDIUM contribution for supported setting facts"]'::jsonb,'["environment category","background","equipment context"]'::jsonb,'["visual observations","trusted metadata/context"]'::jsonb,'["Tight framing may make detailed environment UNKNOWN"]'::jsonb,'["Do not infer a clinic or exact location from weak aesthetic cues"]'::jsonb,'Use broad indoor/outdoor/unknown setting when finer classification is unsupported.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','CINEMATOGRAPHY',12,'Cinematography','Describe how the media was captured, including technical visual quality.','Support capture-style and quality-based discovery.','["Applies to usable visual media"]'::jsonb,'["close-up","extreme close-up","medium","wide","front angle","side angle","handheld","static","moving camera","orientation","camera movement","technical quality","blur","focus","exposure"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct frame or sequence evidence"]'::jsonb,'["COMPLETE when applicable capture/quality categories were evaluated","Observed blur does not make completeness PARTIAL"]'::jsonb,'["MEDIUM/HIGH contribution when capture qualities are requested"]'::jsonb,'["shot size","angle","motion","orientation","quality"]'::jsonb,'["visual observations","scene/event structure","technical/file metadata"]'::jsonb,'["Low-quality imagery can still yield a COMPLETE cinematography evaluation"]'::jsonb,'["Do not translate technical quality into unsupported semantic content"]'::jsonb,'Record supported capture facts even when semantic subjects remain unknown.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','COMPOSITION',13,'Composition','Describe spatial framing and visual arrangement.','Support framing, prominence, and layout queries.','["Applies to usable visual media"]'::jsonb,'["primary subject","central/off-center framing","foreground/background","subject prominence","treatment area prominence","single/multiple subject composition","face/scalp/body prominence","visual clutter"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Direct spatial/frame evidence"]'::jsonb,'["COMPLETE when applicable composition categories were evaluated"]'::jsonb,'["MEDIUM contribution for supported composition facts"]'::jsonb,'["primary subject","framing","prominence","subject count"]'::jsonb,'["visual observations"]'::jsonb,'["Blur may affect semantic identification without preventing layout evaluation"]'::jsonb,'["Do not infer treatment or identity from prominence"]'::jsonb,'Describe geometry and prominence without guessing subject semantics.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','SPEECH_TRANSCRIPT_AUDIO',14,'Speech / Transcript / Audio','Represent usable audio and speech evidence.','Capture trusted audio, speech, language, and transcript evidence without fabrication.','["No audio track is NOT_APPLICABLE","Audio without speech uses the ontology no-speech state","Unintelligible speech makes transcript/language facts UNKNOWN"]'::jsonb,'["has_audio","has_speech","language","transcript chunks","speaker labels","spoken summary","audio event","confidence","timestamps"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Audio-track probe and accepted audio/speech processing output"]'::jsonb,'["COMPLETE when applicability was evaluated and all usable speech processed under audio policy","Silent/no-audio files may be COMPLETE/NOT_APPLICABLE rather than PARTIAL"]'::jsonb,'["Include only trusted/accepted transcript and audio evidence"]'::jsonb,'["accepted transcript","language","audio event","timestamps"]'::jsonb,'["speech/audio","technical/file metadata"]'::jsonb,'["Unintelligible speech is UNKNOWN and never fabricated"]'::jsonb,'["Never invent transcript, language, speaker, or audio events"]'::jsonb,'Continue all non-audio layers and indexing when audio is missing or unusable.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','OCR_VISIBLE_TEXT',15,'OCR / Visible Text','Represent visible readable text.','Capture trusted visible text with spatial and temporal provenance.','["No visible text is NOT_APPLICABLE","Visible but unreadable text is UNKNOWN","Readable text is OBSERVED with transcription and confidence"]'::jsonb,'["detected text","location/region","scene/time","confidence","accepted/rejected search status"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Frame/region evidence and OCR confidence/acceptance decision"]'::jsonb,'["COMPLETE when applicable frames/scenes were evaluated under OCR policy","Zero text is not extraction failure"]'::jsonb,'["Include only accepted/trusted OCR"]'::jsonb,'["accepted text","location/region","scene/time"]'::jsonb,'["OCR/visible text","visual observations","scene/event structure"]'::jsonb,'["Unreadable visible text is UNKNOWN"]'::jsonb,'["Never hallucinate text","Unreadable OCR does not prove no text exists"]'::jsonb,'Continue visual indexing when OCR is absent, unreadable, or rejected.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','MARKETING_CONTENT_USAGE',16,'Marketing & Content Usage','Describe content characteristics useful for discovery and distribution planning without representing consent.','Support content-planning queries while keeping governance separate.','["Evaluate defined marketing-content categories when supportable"]'::jsonb,'["testimonial potential","procedure footage","portrait content","before/after suitability","educational content","promotional candidate","social-media suitability","orientation suitability","quality limitations"]'::jsonb,'["OBSERVED","FALSE","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Grounded content, orientation, and quality evidence"]'::jsonb,'["COMPLETE when defined marketing-content categories were evaluated"]'::jsonb,'["Include only when relevant to the query"]'::jsonb,'["content type","potential use","orientation suitability","quality limitations"]'::jsonb,'["visual observations","scene/event structure","semantic narrative","technical/file metadata"]'::jsonb,'["Record limitations explicitly"]'::jsonb,'["Marketing suitability is not patient consent","Do not infer ACL, rights, or consent"]'::jsonb,'Return UNKNOWN suitability where content evidence is insufficient; governance remains external.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','SEMANTIC_NARRATIVE',17,'Semantic Narrative','Create evidence-grounded human-readable summaries of the asset and important scenes/events.','Provide readable synthesis without creating new facts.','["Generate required narrative forms from available trusted evidence"]'::jsonb,'["short description","detailed/master description","scene narrative","narrative claims","evidence linkage","confidence/uncertainty","search eligibility status"]'::jsonb,'["OBSERVED","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Every factual narrative claim links to trusted structured evidence"]'::jsonb,'["COMPLETE when required narratives were generated and every factual claim is grounded"]'::jsonb,'["Include only narratives eligible under the locked grounded-narrative policy"]'::jsonb,'["short description","master description","grounded scene narrative"]'::jsonb,'["structured semantic assertions","scene/event structure","trusted metadata/context"]'::jsonb,'["Narrative must expose material uncertainty"]'::jsonb,'["Narrative may not create facts unsupported by structured semantic evidence"]'::jsonb,'Produce a narrower narrative from reliable evidence rather than filling gaps.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null),
('kdi_semantic_18_layer_v1','SEARCH_EMBEDDINGS',18,'Search & Embeddings','Create reusable search representations from trusted semantic evidence.','Provide the primary retrieval representation with complete evidence lineage.','["Build from all reliable available evidence","No single modality is mandatory"]'::jsonb,'["canonical search document","normalized search text","positive concepts","supported negative concepts","search-document fingerprint","text embedding","visual embedding where applicable","scene embedding where applicable","embedding provider/model/version","dimension","evidence lineage"]'::jsonb,'["OBSERVED","UNKNOWN","NOT_APPLICABLE"]'::jsonb,'["Every included representation traces to trusted evidence and the current locked semantic version"]'::jsonb,'["COMPLETE when all required representations applicable to the asset were built","An unavailable modality alone does not make the layer PARTIAL"]'::jsonb,'["PRIMARY RETRIEVAL REPRESENTATION","Combine relevant available evidence; do not privilege a fixed primary field"]'::jsonb,'["canonical search document","normalized search text","concepts","embeddings","provider/model/version","evidence lineage"]'::jsonb,'["all reliable available modalities"]'::jsonb,'["Exclude rejected, hallucinated, or ungrounded material"]'::jsonb,'["Do not require audio, OCR, treatment, identity, or any single modality","Do not include unsupported negative concepts"]'::jsonb,'Build the applicable subset of search representations from trusted available evidence.','6da50e2153f6fcb6c9ef27c308ad44d0d2024e702e3faad47586b0068ba64fd7',false,null);

update public.semantic_layer_definitions d set description=v.description
from public.semantic_layer_definition_versions v
where v.spec_version='kdi_semantic_18_layer_v1' and v.layer_id=d.layer_id and d.description='';

update public.semantic_layer_definition_versions set locked=true,locked_at=now(),updated_at=now()
where spec_version='kdi_semantic_18_layer_v1';
update public.semantic_specifications set status='LOCKED',locked=true,locked_at=now(),updated_at=now()
where spec_version='kdi_semantic_18_layer_v1';

alter table public.semantic_specifications enable row level security;
alter table public.semantic_layer_definition_versions enable row level security;
create policy semantic_specifications_read on public.semantic_specifications for select to authenticated using(locked);
create policy semantic_layer_definition_versions_read on public.semantic_layer_definition_versions for select to authenticated using(locked);
revoke insert,update,delete on public.semantic_specifications,public.semantic_layer_definition_versions from anon,authenticated;
grant select on public.semantic_specifications,public.semantic_layer_definition_versions to authenticated;
comment on table public.semantic_specifications is 'Canonical version registry for immutable semantic extraction specifications.';
comment on table public.semantic_layer_definition_versions is 'Versioned rich semantic layer definitions; locked versions are immutable.';
commit;
